import android.view.View;

import com.german_software_engineers.trainerapp.Model.Exercise;
import com.german_software_engineers.trainerapp.Model.Schedule;
import com.german_software_engineers.trainerapp.Model.ScheduleAvailableException;

import java.io.FileOutputStream;

public class AddExerciseActivity extends AppCompatActivity implements ExcersizeListFragment.OnListFragmentInteractionListener {

    String ScheduleName;
    ExcersizeListFragment fragment;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        Intent intent = getIntent();
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_add_exercise);
        Toolbar toolbar = (Toolbar) findViewById(R.id.toolbar);
        setSupportActionBar(toolbar);

        FloatingActionButton fab = (FloatingActionButton) findViewById(R.id.fab);
        fab.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View view) {
                finished();
            }
        });
        getSupportActionBar().setDisplayHomeAsUpEnabled(true);

        ScheduleName = intent.getStringExtra("scheduleName");
        fragment = ExcersizeListFragment.newInstance(1,ScheduleName);
        getSupportFragmentManager().beginTransaction().replace(R.id.excEdit, fragment ).commit();
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        // Inflate the menu; this adds items to the action bar if it is present.
        getMenuInflater().inflate(R.menu.add_exercise_menu, menu);
        return true;
    }

    public void openExerciseDialog(){
        ExerciseDialog dialog = new ExerciseDialog();
        try {
            dialog.setSchedule(ApplicationHandler.getModel().getSchedule(ScheduleName));
        } catch (ScheduleAvailableException e) {
            e.printStackTrace();
        }
        dialog.show(getSupportFragmentManager(),"ExerciseDialog");
//
//        if(exc!=null) {
//            try {
//                ApplicationHandler.getModel().getSchedule(ScheduleName).addExercise(exc);
//            } catch (ScheduleAvailableException e) {
//                e.printStackTrace();
//            }
//        }else
//        {
//            Log.i("openExerciseDialog","Somethings Wrong");
//        }
//        try {
//            fragment.getAdatpoer().notifyItemRangeChanged(0,ApplicationHandler.getModel().getSchedule(ScheduleName).exercises().size());
//        } catch (ScheduleAvailableException e) {
//            e.printStackTrace();
//        }
    }

    @Override
    public void onListFragmentInteraction(Exercise item) {

    }

    public void finished(){
        try {
            FileOutputStream outputStream = openFileOutput(ApplicationHandler.FileName, MODE_PRIVATE);
            String  value = ApplicationHandler.getModel().getGson();
            outputStream.write(value.getBytes());
            outputStream.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
        Intent intent = new Intent(this, TrainingScheduleEditor.class);
        startActivity(intent);
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        // Handle item selection
        switch (item.getItemId()) {
            case R.id.action_addExercise:
                openExerciseDialog();
                return true;
            case R.id.action_settings:
                //showHelp();
                return true;
            default:
                return super.onOptionsItemSelected(item);
        }
    }
}

package com.german_software_engineers.trainerapp;


import android.app.AlertDialog;
import android.app.Dialog;
import android.content.DialogInterface;
import android.os.Bundle;
import android.support.v4.app.DialogFragment;
import android.widget.CheckBox;
import android.widget.TextView;

import com.german_software_engineers.trainerapp.Model.Exercise;
import com.german_software_engineers.trainerapp.Model.Schedule;

public class ExerciseDialog extends DialogFragment {
    Dialog dialog;
    Schedule Schedule = null;

    @Override
    public Dialog onCreateDialog(Bundle savedInstanceState) {
        AlertDialog.Builder builder = new AlertDialog.Builder(getActivity());

        builder.setView(R.layout.exersice_dialog)
                .setPositiveButton(R.string.ok, new DialogInterface.OnClickListener() {
                    public void onClick(DialogInterface dialog, int id) {
                        generateExcercise();
                    }
                })
                .setNegativeButton(R.string.cancel, new DialogInterface.OnClickListener() {
                    public void onClick(DialogInterface dialog, int id) {
                        dialog.cancel();
                    }
                });
        dialog = builder.create();
        return dialog;
    }

    public void generateExcercise(){
        String name = ((TextView)dialog.findViewById(R.id.exerciseName)).getText().toString();

        boolean isSeatActivated = ((CheckBox)dialog.findViewById(R.id.seatCheckBox)).isChecked();
        Integer seatPos = 0;
        if(isSeatActivated)
            seatPos = Integer.valueOf(((TextView)dialog.findViewById(R.id.SeatEdit)).getText().toString());

        boolean isLegActivated = ((CheckBox)dialog.findViewById(R.id.LegCheckBox)).isChecked();
        Integer LegPos = 0;
        if(isLegActivated)
            LegPos = Integer.valueOf(((TextView)dialog.findViewById(R.id.LegEdit)).getText().toString());

        boolean isFootActivated = ((CheckBox)dialog.findViewById(R.id.FootCheckBox)).isChecked();
        Integer footPos = 0;
        if(isFootActivated)
            footPos = Integer.valueOf(((TextView)dialog.findViewById(R.id.FootEdit)).getText().toString());

        boolean isAngnleActivated = ((CheckBox)dialog.findViewById(R.id.AngleCheckBox)).isChecked();
        Integer anglePos = 0;
        if(isAngnleActivated)
            anglePos = Integer.valueOf(((TextView)dialog.findViewById(R.id.AngleEdit)).getText().toString());

        boolean isBackActivated = ((CheckBox)dialog.findViewById(R.id.BackCheckBox)).isChecked();
        Integer backPos = 0;
        if(isAngnleActivated)
            backPos = Integer.valueOf(((TextView)dialog.findViewById(R.id.BackEdit)).getText().toString());

        boolean isWeightActivated = ((CheckBox)dialog.findViewById(R.id.WeightCheckBox)).isChecked();
        Double weight = 0.0;
        if(isWeightActivated)
            weight = Double.valueOf(((TextView)dialog.findViewById(R.id.WeightEdit)).getText().toString());

        Exercise exc = new Exercise(name,isSeatActivated, isLegActivated,isFootActivated,isAngnleActivated,isWeightActivated, isBackActivated);
        exc.setAnglePosition(anglePos.intValue());
        exc.setFootPosition(footPos.intValue());
        exc.setLegPosition(LegPos.intValue());
        exc.setSeatPosition(seatPos.intValue());
        exc.setWeight(weight.doubleValue());
        exc.setBackPosition(backPos.intValue());

        Schedule.addExercise(exc);
    }

    public void setSchedule(Schedule schedule){
        Schedule = schedule;
    }
}

